healthy=next(v for v in final['runs'] if v['definition']['name'].endswith('whole-pilot barrier'));ticks=[];forces=[];kinetic=[];trigger=healthy['metrics']['impactDetail']['triggerTick']
with (Path(healthy['archivePath'])/'detail.rort').open('rb') as f:
 f.read(32)
 while f.read(4)==b'DATA':
  n,length,crc=struct.unpack('<III',f.read(12));data=f.read(length);assert zlib.crc32(data)==crc and f.read(4)==b'DONE'
  tick,dt=struct.unpack_from('<Qd',data);nodes,beams,contacts=struct.unpack_from('<III',data,20);net=[0.,0.,0.];offset=128+nodes*256+beams*112
  for j in range(contacts):
   at=offset+j*104
   if struct.unpack_from('<I',data,at+12)[0]:
    applied=struct.unpack_from('<3f',data,at+64)
    for c in range(3):net[c]+=applied[c]
  ticks.append((tick-trigger)*dt);forces.append(net);kinetic.append(struct.unpack_from('<d',data,96)[0])
fig,axes=plt.subplots(2,1,figsize=(10,5),sharex=True)
for c,color in enumerate(['#52c9b9','#7399c1','#f7bc6a']):axes[0].plot(ticks,[f[c]/1000 for f in forces],color=color,label='XYZ'[c],lw=1)
axes[0].legend(loc='upper right');axes[0].set_ylabel('Net barrier force · kN');axes[0].set_title('Actual native detail: vector applications and movable-node kinetic energy')
axes[1].plot(ticks,[k/1000 for k in kinetic],color='#52c9b9');axes[1].set_ylabel('Kinetic energy · kJ');axes[1].set_xlabel('Physics seconds relative to first consumed barrier contact')
for ax in axes:ax.axvline(0,color='#bfcedb',ls='--',lw=.7);ax.grid(alpha=.3)
save(fig,'native-forces.png')
def url(p):return html.escape(Path(p).resolve().as_uri(),quote=True)
def image(name,caption):return '<figure><a href="'+url(media/name)+'"><img loading="lazy" src="'+url(media/name)+'" alt="'+html.escape(caption)+'"></a><figcaption>'+html.escape(caption)+' Click to open full resolution.</figcaption></figure>'
def link(p,label):return '<a href="'+url(p)+'">'+html.escape(label)+'</a>'
def table(headers,rows):return '<div class="table"><table><thead><tr>'+''.join('<th>'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
